import math, sys
sys.path.insert(0, "/app")
from mock_env import MockEnv


def make_v3(spike_ratio=1.4, s_min_alpha=0.25, bc_alpha=0.4, root_k=math.sqrt(1.5)):
    def run(env):
        n = env.n_segments
        b_min, b_max = env.b_min, env.b_max
        t_overhead, throughput = env.t_overhead, env.throughput

        def clip(b):
            return max(b_min, min(b_max, b))

        s_min_est = None
        bc_est = None
        b_star = clip(math.sqrt(b_min * b_max))

        def predict(b):
            if s_min_est is None or bc_est is None:
                return None
            return s_min_est * (1 + bc_est / b)

        def b_of(bc):
            return clip(math.sqrt(max(bc, 1e-9) * t_overhead * throughput))

        prev = None  # (batch, steps) most recent observation, for 2-point solve
        toggle = False
        i = 0
        while i < n:
            if toggle:
                b = clip(b_star * root_k)
            else:
                b = clip(b_star / root_k)
            toggle = not toggle

            pred = predict(b)
            r = env.run_segment(b)
            steps = r['steps']

            spiked = False
            if pred is not None and pred > 0 and steps > spike_ratio * pred:
                # solve directly for new bc holding s_min_est fixed
                if s_min_est is not None and s_min_est > 0:
                    ratio = steps / s_min_est - 1.0
                    if ratio > 0:
                        bc_new = b * ratio
                        bc_est = bc_new
                        b_star = b_of(bc_est)
                        spiked = True

            if not spiked and prev is not None and prev[0] != b and prev[1] > 0 and steps > 0:
                x1, x2 = 1.0 / prev[0], 1.0 / b
                s1, s2 = prev[1], steps
                slope = (s1 - s2) / (x1 - x2)
                intercept = s2 - slope * x2
                if intercept > 0 and slope > 0:
                    bc_new = slope / intercept
                    if s_min_est is None:
                        s_min_est = intercept
                        bc_est = bc_new
                    else:
                        s_min_est = (1 - s_min_alpha) * s_min_est + s_min_alpha * intercept
                        bc_est = math.exp((1 - bc_alpha) * math.log(bc_est) + bc_alpha * math.log(bc_new)) if bc_est else bc_new
                    b_star = b_of(bc_est)
            elif s_min_est is None:
                # bootstrap fallback if first point alone
                pass

            prev = (b, steps)
            i += 1
    return run


def test_scenario(sched_factory, switch, jump, growth, seed):
    env = MockEnv(switch=switch, jump=jump, growth=growth, seed=seed)
    sched = sched_factory()
    sched(env)
    achieved = env.total
    env2 = MockEnv(switch=switch, jump=jump, growth=growth, seed=seed)
    oracle = env2.optimal_cost()
    env3 = MockEnv(switch=switch, jump=jump, growth=growth, seed=seed)
    const = env3.best_constant_cost()
    score = (const - achieved) / (const - oracle) if const != oracle else float('nan')
    return achieved, oracle, const, score


def run_suite(sched_factory, label, jumps=(4,7,10,20)):
    scenarios = []
    for switch in [3, 8, 15, 20, 25, 30, 35, 38]:
        for jump in jumps:
            for growth in [1.0, 1.03, 1.06, 1.10]:
                for seed in [1, 2, 3]:
                    scenarios.append((switch, jump, growth, seed))
    rows = []
    for sc in scenarios:
        achieved, oracle, const, score = test_scenario(sched_factory, *sc)
        gap = const - oracle
        rows.append((sc, achieved, oracle, const, gap, score))
    meaningful = [r for r in rows if r[4] / r[3] > 0.05]
    mscores = sorted(r[5] for r in meaningful)
    print(f"--- {label} ---  n={len(meaningful)}")
    print("min:", round(mscores[0],3), "p10:", round(mscores[len(mscores)//10],3), "median:", round(mscores[len(mscores)//2],3),
          "mean:", round(sum(mscores)/len(mscores),3), "frac<0.9:", round(sum(1 for s in mscores if s<0.9)/len(mscores),3))
    worst = sorted(meaningful, key=lambda r: r[5])[:6]
    for r in worst:
        print(f"  switch/jump/growth/seed={r[0]} achieved={r[1]:.3f} oracle={r[2]:.3f} const={r[3]:.3f} score={r[5]:.3f}")
    return mscores


run_suite(lambda: make_v3(), "v3 reactive")

